{
  "title": "The Glass Diver's Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "Mara studies a map of the ruined city.",
      "visual_description": "A windswept hilltop at dusk; ink-stained coat flapping, brass compass open, a parchment map showing a broken royal skyline below.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 2,
      "caption": "The oracle lamp warns of the road ahead.",
      "visual_description": "An oil lamp with a single glowing eye in its flame, casting long shadows on a cracked stone road leading into the dead city.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 3,
      "caption": "The tin fox scouts the castle gates.",
      "visual_description": "A small clockwork fox with blue glass eyes crouched at a massive iron gate, its key-wind tail ticking softly under a torn royal banner.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 4,
      "caption": "Glass Diver steps out of a broken window.",
      "visual_description": "A figure in a clear diving helmet emerging from a shattered stained-glass pane, coat shimmering with reflected broken city lights.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 5,
      "caption": "The rescuers meet in the gatehouse shadow.",
      "visual_description": "Mara, the glass diver, the lamp, and the tin fox huddled beneath a fallen archway draped with frayed royal banners.",
      "characters": ["mara_the_cartographer", "glass_diver", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 6,
      "caption": "They pass beneath the cursed tower.",
      "visual_description": "A leaning black tower wreathed in green smoke; the lamp's eye flickers wary, Mara shields her compass from the haze.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 7,
      "caption": "An armored patrol marches the avenue.",
      "visual_description": "Helmeted silhouettes with plumed pikes crossing a moonlit boulevard; the tin fox flattens behind a toppled fountain.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 8,
      "caption": "The sleeping tax collector blocks the doorway.",
      "visual_description": "A round official slumped against a counting-house door, ledger book as pillow, stamped papers stuck to his sleeves, snoring loudly.",
      "characters": ["sleeping_tax_collector", "mara_the_cartographer"]
    },
    {
      "scene_number": 9,
      "caption": "Glass Diver slips into a mirrored hall.",
      "visual_description": "The diver wading waist-deep into a tall mirror as if into water, ripples spreading across the silvered glass of a derelict ballroom.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 10,
      "caption": "The tin fox finds the captive's trail.",
      "visual_description": "Clockwork fox pawing at a torn scrap of cloth in a corridor lit by guttering candles, blue eyes glinting.",
      "characters": ["tin_fox", "mara_the_cartographer"]
    },
    {
      "scene_number": 11,
      "caption": "The oracle lamp deciphers a magic door.",
      "visual_description": "A heavy door etched with shifting runes; the lamp held close, its single eye matching glyphs with light.",
      "characters": ["oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 12,
      "caption": "A roar shakes the rooftops above.",
      "visual_description": "Tiles trembling as a vast winged shadow sweeps past chimney stacks; the diver crouches reflected in a puddle.",
      "characters": ["glass_diver", "tin_fox"]
    },
    {
      "scene_number": 13,
      "caption": "They wake the dozing official for a key.",
      "visual_description": "Mara tugs a brass key from the sleeping tax collector's stamped sleeve while he mumbles in his sleep, ledger sliding off his lap.",
      "characters": ["mara_the_cartographer", "sleeping_tax_collector"]
    },
    {
      "scene_number": 14,
      "caption": "Glass Diver dives through a throne-room window.",
      "visual_description": "The diver plunging headfirst into a tall arched window, coat trailing reflected chandeliers and broken crown shapes.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 15,
      "caption": "The captive is freed from a guarded cell.",
      "visual_description": "Glass Diver lifting a frightened figure away from chained shackles; the tin fox stands lookout at the iron-barred door.",
      "characters": ["glass_diver", "tin_fox"]
    },
    {
      "scene_number": 16,
      "caption": "The lamp warns of patrols at the courtyard.",
      "visual_description": "Oracle lamp swinging its eye toward distant torchlight in a rubble-strewn courtyard; Mara unfurls an escape map.",
      "characters": ["oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 17,
      "caption": "The team sprints across the river bridge.",
      "visual_description": "An ancient stone bridge over black water; Mara, the diver, the lamp swinging wildly, and the tin fox racing past collapsing balustrades.",
      "characters": ["mara_the_cartographer", "glass_diver", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 18,
      "caption": "Dawn over the far bank, the city behind them.",
      "visual_description": "Sunrise light on a misty riverbank; Mara folds her map, the diver's helmet catches pink light, the lamp dims, the tin fox sits with ticking tail.",
      "characters": ["mara_the_cartographer", "glass_diver", "oracle_lamp", "tin_fox"]
    }
  ]
}

